from pyspark import pipelines as dp
from pyspark.sql.functions import *

# Bronze: Raw clinical trial data
@dp.table
def raw_trials():
    return spark.readStream.format('cloudFiles').load('/raw/trials')

# Silver: Validated trials — drop rows with null patient
@dp.table
def clean_trials():
    dp.__BLANK_0__('valid_patient', col('patient_id').isNotNull())
    return dp.read_stream('raw_trials')

# Warn but keep rows with unusual dosage
@dp.table
def validated_trials():
    dp.__BLANK_1__('valid_dosage', (col('dosage') >= 0.1) & (col('dosage') <= 1000))
    # Fail the entire pipeline if trial_id format is wrong
    dp.__BLANK_2__('valid_trial', col('trial_id').rlike('^CT-[0-9]+$'))
    return dp.read_stream('clean_trials')

# Gold: Aggregate by trial
@dp.table
def trial_summary():
    return (
        dp.__BLANK_3__('validated_trials')
        .groupBy('trial_id')
        .agg(
            count('patient_id').alias('patient_count'),
            avg('__BLANK_4__').alias('avg_dosage')
        )
    )

# Quarantine: Capture dropped records
@dp.table
def quarantine_trials():
    return (
        dp.read_stream('raw_trials')
        .filter(col('patient_id').is__BLANK_5__())
    )
